<?php

namespace App\Models;

use App\Services\Kyc\KycAuthority;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use InvalidArgumentException;

/**
 * KYC-002 — ONE PRIVATE DOCUMENT: WHERE IT IS, WHAT IT IS, WHO REVIEWED IT, WHEN IT LAPSES.
 * =================================================================================================
 *
 * THE ROW IS NOT THE DOCUMENT. It holds `disk` + `storage_name`, and `storage_name` is 64 hex
 * characters generated by `random_bytes(32)` under `<store>/<authority>/`, with NO extension. The
 * bytes are only reachable through `App\Services\Kyc\KycDocumentStore::readForActor()`, which
 * writes the access-log row in the same call — so there is no way to read a document that does not
 * also record the read. That is KYC-002's fourth clause, and it is enforced by having ONE reader
 * rather than by asking every caller to remember.
 *
 * WHY THE NAME CARRIES THE ENTROPY AND THE DIRECTORY DOES NOT, measured and not comfortable: on the
 * deployed host the document root IS the repository root and the `.htaccess` deliberately carries no
 * deny rules (owner's standing instruction, P1-SEC-40). The project's own measurement in that file
 * records `GET /storage/logs/laravel.log -> 200`, so a file anywhere under the repository is
 * fetchable BY A CLIENT THAT KNOWS ITS PATH. The written deny rules
 * (`docs/security/p1-sec-40-apache-deny.conf` GROUP 2) already refuse `^/storage/(logs|framework|app)`,
 * which covers this disk's default root — but they are not active. So:
 *
 *   what engineering CAN guarantee   the path is not guessable (2^256), is never emitted as a URL,
 *                                   has no extension a server could map to a handler, and lives
 *                                   outside every public tree.
 *   what it CANNOT guarantee here   that a client who learns the path is refused. That needs the
 *                                   deny rules activated, which is the owner's call.
 *
 * Both halves are stated because overstating the first one is how a control becomes a belief.
 *
 * NOT `Cachable` and NOT in `scoped_models`, for the reasons in `KycVerification`'s docblock. Every
 * read carries its own `store_id` predicate.
 *
 * `authority` AND `store_id` ARE DENORMALISED FROM THE PROFILE and the `saving` guard below refuses
 * a row whose values disagree with it. Without that guard the denormalisation would be a second
 * place for the truth to live, which is how `Setting` ended up with a cross-tenant writer.
 */
class KycDocument extends Model
{
    protected $table = 'kyc_documents';

    /**
     * NEITHER THE LOCATION NOR THE IDENTITY OF THE FILE IS FILLABLE. `disk`, `storage_name`,
     * `sha256`, `size_bytes`, `mime`, `store_id`, `authority` and `kyc_verification_id` are set by
     * `KycDocumentStore` from the file it actually wrote and from the profile it was handed — never
     * from a request. A fillable `storage_name` would be a request-named path, which is the
     * single most productive defect shape in this codebase.
     */
    protected $fillable = [
        'document_kind',
        'original_name',
        'issued_on',
        'expires_on',
        'status',
        'reviewed_by',
        'reviewed_at',
        'review_note',
        'uploaded_by',
    ];

    protected $casts = [
        'issued_on' => 'date',
        'expires_on' => 'date',
        'reviewed_at' => 'datetime',
        'size_bytes' => 'integer',
    ];

    /** Uploaded, nobody has decided. */
    public const PENDING = 'pending';

    public const APPROVED = 'approved';

    public const REJECTED = 'rejected';

    /** A newer document of the same kind replaced it. Kept, because the trail refers to it. */
    public const SUPERSEDED = 'superseded';

    /** `expires_on` has passed. `KycRenewal` is the only writer of this state. */
    public const EXPIRED = 'expired';

    /** @var list<string> pinned against the migration's comment by KycStatusVocabularyTest */
    public const STATUSES = [
        self::PENDING,
        self::APPROVED,
        self::REJECTED,
        self::SUPERSEDED,
        self::EXPIRED,
    ];

    /**
     * REFUSE A ROW THAT DISAGREES WITH ITS PROFILE, or carries an unknown vocabulary value.
     *
     * The profile is read `withoutGlobalScopes()` for the reason `UserPolicy::tenantRootIsAMerchant()`
     * gives about its own read: there is no scope on this model today, but a future one must not be
     * able to turn this lookup into `null` and thereby turn a disagreement into a pass. A profile
     * that cannot be read is a refusal, not a default.
     */
    protected static function booted(): void
    {
        static::saving(function (self $document): void {
            if (! KycAuthority::isKnown((string) $document->authority)) {
                throw new InvalidArgumentException(
                    'a KYC document must name a known authority, not ' . json_encode($document->authority)
                );
            }

            if (! in_array((string) $document->status, self::STATUSES, true)) {
                throw new InvalidArgumentException(
                    'a KYC document must carry a known status, not ' . json_encode($document->status)
                );
            }

            if ((int) $document->store_id <= 0) {
                throw new InvalidArgumentException('a KYC document must belong to a store');
            }

            $profile = KycVerification::withoutGlobalScopes()
                ->whereKey($document->kyc_verification_id)
                ->first();

            if ($profile === null) {
                throw new InvalidArgumentException('a KYC document must belong to a verification record that exists');
            }

            if ((int) $profile->store_id !== (int) $document->store_id
                || (string) $profile->authority !== (string) $document->authority) {
                throw new InvalidArgumentException(
                    'a KYC document must carry the same store and authority as its verification record'
                );
            }
        });
    }

    /** @return BelongsTo<KycVerification, KycDocument> */
    public function verification(): BelongsTo
    {
        return $this->belongsTo(KycVerification::class, 'kyc_verification_id');
    }

    /**
     * Is this document an APPROVAL THAT IS STILL GOOD TODAY? Same shape, and the same deliberate
     * pessimism, as `KycVerification::isCurrent()`: the stored date decides, not a scheduled job.
     */
    public function isCurrent(?\DateTimeInterface $asOf = null): bool
    {
        if ((string) $this->status !== self::APPROVED) {
            return false;
        }

        if ($this->expires_on === null) {
            return true;
        }

        $grace = max(0, (int) config('kyc.expiry_grace_days', 0));

        return $this->expires_on->copy()->endOfDay()->addDays($grace)
            ->greaterThanOrEqualTo($asOf ?? now());
    }
}
